{"content": "from abc import ABC, abstractmethod
from dataclasses import dataclass


# --- Domain ---

class PricingRule(ABC):
    @abstractmethod
    def applies_to(self, item_type: str) -> bool: ...

    @abstractmethod
    def adjust(self, value: float) -> float: ...


class TypeARule(PricingRule):
    def applies_to(self, item_type: str) -> bool:
        return item_type == 'A'

    def adjust(self, value: float) -> float:
        return value * 1.1


class TypeBRule(PricingRule):
    def applies_to(self, item_type: str) -> bool:
        return item_type == 'B'

    def adjust(self, value: float) -> float:
        return value * 0.9


class TypeCRule(PricingRule):
    def applies_to(self, item_type: str) -> bool:
        return item_type == 'C'

    def adjust(self, value: float) -> float:
        return value * 1.05


DEFAULT_RULES: list[PricingRule] = [TypeARule(), TypeBRule(), TypeCRule()]


# --- Application ---

@dataclass
class Item:
    type: str
    value: float


class PriceCalculator:
    def __init__(self, rules: list[PricingRule] | None = None):
        self._rules = rules or DEFAULT_RULES

    def _resolve_rule(self, item_type: str) -> PricingRule:
        for rule in self._rules:
            if rule.applies_to(item_type):
                return rule
        raise ValueError(f"Unknown item type: {item_type!r}")

    def calculate(self, items: list[Item]) -> float:
        return sum(self._resolve_rule(item.type).adjust(item.value) for item in items)
